import decimal
from dataclasses import dataclass
from decimal import Decimal

from .money import money_context
from .rules import Rule, categorize
from .transactions import Transaction


@dataclass(frozen=True)
class CategoryAgg:
    category: str
    count: int
    income: Decimal
    expenses: Decimal
    net: Decimal


@dataclass(frozen=True)
class MonthAgg:
    month: str
    count: int
    income: Decimal
    expenses: Decimal
    net: Decimal
    categories: list[CategoryAgg]


def dedupe(txs: list[Transaction]) -> tuple[list[Transaction], int]:
    seen = set()
    kept = []
    for tx in txs:
        key = (tx.date, tx.description, tx.amount)
        if key not in seen:
            seen.add(key)
            kept.append(tx)
    return kept, len(txs) - len(kept)


def filter_month(txs: list[Transaction], month: str | None) -> list[Transaction]:
    if month is None:
        return list(txs)
    return [t for t in txs if t.date[:7] == month]


def categorized(
    txs: list[Transaction], rules: list[Rule]
) -> list[tuple[Transaction, str]]:
    pairs = [(t, categorize(t.description, rules)) for t in txs]
    return sorted(pairs, key=lambda p: p[0].date)


def aggregate(pairs: list[tuple[Transaction, str]]) -> list[MonthAgg]:
    groups: dict[tuple[str, str], list[Transaction]] = {}
    for tx, cat in pairs:
        groups.setdefault((tx.date[:7], cat), []).append(tx)
    months: dict[str, list[CategoryAgg]] = {}
    with decimal.localcontext(money_context()):
        for (month, cat) in sorted(groups):
            amounts = [t.amount for t in groups[(month, cat)]]
            inc = sum((a for a in amounts if a > 0), Decimal(0))
            exp = sum((a for a in amounts if a < 0), Decimal(0))
            months.setdefault(month, []).append(
                CategoryAgg(cat, len(amounts), inc, exp, inc + exp)
            )
        out = []
        for month, cats in months.items():
            inc = sum((c.income for c in cats), Decimal(0))
            exp = sum((c.expenses for c in cats), Decimal(0))
            out.append(
                MonthAgg(month, sum(c.count for c in cats), inc, exp, inc + exp, cats)
            )
    return out

